#### Example 1: Service Implementation

```python
# User Service Implementation
from fastapi import FastAPI, Depends
from src.adapters.web.handlers import UserHandler
from src.adapters.persistence.user_repository import PostgresUserRepository
from src.domain.services.user_service import UserService

app = FastAPI(title="User Service", version="1.0.0")

# Dependency injection
def get_user_repository():
    return PostgresUserRepository()

def get_user_service(repo = Depends(get_user_repository)):
    return UserService(repo)

def get_user_handler(service = Depends(get_user_service)):
    return UserHandler(service)

# Routes
@app.post("/api/v1/users")
async def create_user(request: CreateUserRequest, handler = Depends(get_user_handler)):
    return await handler.create_user(request)

@app.get("/api/v1/users/{user_id}")
async def get_user(user_id: str, handler = Depends(get_user_handler)):
    return await handler.get_user(user_id)
```
